mapper.select:
select 
from litemall_coupon_delivery
where deleted = 0
and coupon_id = #{couponId}
order by add_time desc, id desc
limit #{limit} offset #{offset}

select user_id
from litemall_order
where deleted = 0
  and order_status >= 201
  and user_id is not null
group by user_id


    max(coalesce(pay_time, add_time)) >= #{paidSince}


    and count(*) >= #{minFrequency}


    and sum(coalesce(actual_price, 0)) >= #{minMonetary}


order by user_id asc
limit #{limit}
